export type MusicTriviaPhase = 'SETUP' | 'LOADING' | 'GET_READY' | 'COUNTDOWN' | 'PLAYING' | 'BUZZED' | 'ANSWERING' | 'ANSWER_RESULT' | 'REVEAL' | 'ROUND_RESULT' | 'FINISHED';
export type MusicSourceType = 'ITUNES' | 'SPOTIFY' | 'YOUTUBE' | 'DEEZER' | 'SOUNDCLOUD';
export type MusicTriviaMode = 'TYPING' | 'GAME_MASTER';
export interface MusicTriviaTrack {
    id: string;
    previewUrl: string;
    sourceType: MusicSourceType;
    durationMs: number;
    artworkUrl?: string;
}
export interface BuzzerPress {
    playerId: string;
    timestamp: number;
    reactionTimeMs: number;
}
export interface MusicTriviaRound {
    roundNumber: number;
    track: MusicTriviaTrack;
    buzzerPresses: BuzzerPress[];
    currentBuzzerId: string | null;
    struckOutIds: string[];
    answeredCorrectly: boolean;
    winnerId: string | null;
}
export interface MusicTriviaRoundHistory {
    roundNumber: number;
    winnerId: string | null;
    trackTitle: string;
    artistName: string;
    artworkUrl?: string;
    trackViewUrl?: string;
    album?: string;
    releaseYear?: string;
    successfulAnswerText?: string;
}
export interface MusicTriviaState {
    phase: MusicTriviaPhase;
    mode: MusicTriviaMode;
    sourceType: MusicSourceType;
    totalRounds: number;
    currentRound: MusicTriviaRound | null;
    roundHistory: MusicTriviaRoundHistory[];
    readyPlayerIds: string[];
    countdownEndsAt?: number;
    scores: Record<string, number>;
    hostPlays: boolean;
    answerTimeoutMs: number;
    playStartTime?: number;
    errorMessage?: string;
    pausedAtMs?: number;
    revealedAnswer?: {
        title: string;
        artist: string;
        artworkUrl?: string;
        trackViewUrl?: string;
        album?: string;
        releaseYear?: string;
        successfulAnswerText?: string;
    };
}
export type MusicTriviaActionType = 'CONFIGURE_SOURCE' | 'START_ROUND' | 'PLAYER_READY' | 'START_COUNTDOWN' | 'PRESS_BUZZER' | 'GIVE_UP' | 'SUBMIT_ANSWER' | 'HOST_JUDGE' | 'REVEAL_ANSWER' | 'NEXT_ROUND' | 'END_GAME';
export interface MusicTriviaAction {
    type: MusicTriviaActionType;
    query?: string;
    sourceType?: MusicSourceType;
    searchOptions?: {
        country?: string;
        attribute?: string;
        yearStart?: number;
        yearEnd?: number;
    };
    answer?: string;
    correct?: boolean;
}
export interface MusicTriviaTrackAnswerPayload {
    roundNumber: number;
}
export interface MusicTriviaHostAnswerPayload {
    title: string;
    artist: string;
    artworkUrl?: string;
    trackViewUrl?: string;
    album?: string;
    releaseYear?: string;
}
export interface MusicTriviaSyncPlayPayload {
    roundNumber: number;
    playStartTime: number;
    previewUrl: string;
    sourceType: MusicSourceType;
    durationMs: number;
    artworkUrl?: string;
}
